    const hasSuccess = jsonData.hasOwnProperty('success') || jsonData.hasOwnProperty('status') || jsonData.hasOwnProperty('message') || jsonData.hasOwnProperty('data') || jsonData.hasOwnProperty('token') || jsonData.hasOwnProperty('access_token');
    pm.expect(hasSuccess).to.be.true;
})

