        if (!/^\d+$/.test(String(value).trim())) {
            throw new Error(
                key + " must be numeric: " + value
            );
        }

        if (Number(value) <= 0) {
            throw new Error(
                key + " must be greater than zero: " + value
            );
        }

    });

    // ----------------------------------------------
    // Contract month validation
    // ----------------------------------------------

    const monthNumber = Number(contractMonth);
    const yearNumber = Number(contractYear);

    if (
        !Number.isInteger(monthNumber) ||
        monthNumber < 1 ||
        monthNumber > 12
    ) {
        throw new Error(
            "Invalid FUTURE_CONTRACT_MONTH: " + contractMonth
        );
    }

    if (
        !Number.isInteger(yearNumber) ||
        yearNumber < 2000
    ) {
        throw new Error(
            "Invalid FUTURE_CONTRACT_YEAR: " + contractYear
        );
    }

    // ----------------------------------------------
    // FUTURE_CONTRACT validation
    // Expected format: MONTH-YEAR
    // Example: 11-2026
    // ----------------------------------------------

    if (
        futureContract === undefined ||
        futureContract === null ||
        String(futureContract).trim() === ""
    ) {
        throw new Error("FUTURE_CONTRACT is missing.");
    }

    const expectedContract =
        monthNumber + "-" + yearNumber;

    if (
        String(futureContract).trim() !== expectedContract
    ) {
        throw new Error(
            "Invalid FUTURE_CONTRACT. Expected " +
            expectedContract +
            ", got " + futureContract
        );
    }

    console.log("FUTURE_CONTRACT validated:", futureContract);

    // ----------------------------------------------
    // Validate request body
    // ----------------------------------------------

    if (
        !pm.request.body ||
        pm.request.body.mode !== "raw"
    ) {
        throw new Error(
            "Cash Sale requires a raw JSON request body."
        );
    }

    const resolvedBody = pm.variables.replaceIn(
        pm.request.body.raw
    );

    if (/{{[^{}]+}}/.test(resolvedBody)) {
        throw new Error(
            "Unresolved variables found in Cash Sale request body."
        );
    }

    let requestBody;

    try {
        requestBody = JSON.parse(resolvedBody);
        console.log("Cash Sale request JSON is valid.");
    } catch (error) {
        throw new Error(
            "Cash Sale request JSON is invalid: " +
            error.message
        );
    }

    // ----------------------------------------------
    // Validate request fields
    // ----------------------------------------------

    function validateId(field, expectedValue) {

        const actualValue = Number(requestBody[field]);

        if (
            !Number.isInteger(actualValue) ||
            actualValue <= 0 ||
            actualValue !== Number(expectedValue)
        ) {
            throw new Error(
                field +
                " does not match expected value: " +
                expectedValue +
                ". Actual: " +
                requestBody[field]
            );
        }

    }

    validateId("cropId", penId);
    validateId("entityId", entityId);
    validateId("year", year);
    validateId("organization_id", organizationId);
    validateId("contractMonth", contractMonth);
    validateId("contractYear", contractYear);

    // ----------------------------------------------
    // Transaction type validation
    // ----------------------------------------------

    if (
        String(requestBody.transactionTypeCode).toLowerCase()
        !== "cash"
    ) {
        throw new Error(
            "Invalid transactionTypeCode. Expected cash, got " +
            requestBody.transactionTypeCode
        );
    }

    // ----------------------------------------------
    // Quantity validation
    // ----------------------------------------------

    if (
        requestBody.quantity === null ||
        requestBody.quantity === undefined ||
        !Number.isFinite(Number(requestBody.quantity)) ||
        Number(requestBody.quantity) <= 0
    ) {
        throw new Error(
            "Cash Sale quantity must be greater than zero."
        );
    }

    // ----------------------------------------------
    // Number of heads validation
    // ----------------------------------------------

    if (
        requestBody.numberOfHead === null ||
        requestBody.numberOfHead === undefined ||
        !Number.isInteger(Number(requestBody.numberOfHead)) ||
        Number(requestBody.numberOfHead) <= 0
    ) {
        throw new Error(
            "Cash Sale numberOfHead must be a positive integer."
        );
    }

    // ----------------------------------------------
    // Price validation
    // ----------------------------------------------

    if (
        requestBody.price === null ||
        requestBody.price === undefined ||
        !Number.isFinite(Number(requestBody.price)) ||
        Number(requestBody.price) <= 0
    ) {
        throw new Error(
            "Cash Sale price must be greater than zero."
        );
    }

    // ----------------------------------------------
    // Validate FUTURE_CONTRACT in request if present
    // ----------------------------------------------

    if (
        requestBody.futureContract !== undefined &&
        requestBody.futureContract !== null &&
        String(requestBody.futureContract).trim() !==
            expectedContract
    ) {
        throw new Error(
            "Request futureContract mismatch. Expected " +
            expectedContract +
            ", got " +
            requestBody.futureContract
        );
    }

    // ----------------------------------------------
    // Final debug logs
    // ----------------------------------------------

    console.log("Transaction Type:", requestBody.transactionTypeCode);
    console.log("Pen ID:", requestBody.cropId);
    console.log("Entity ID:", requestBody.entityId);
